/**
 * Camera.js
 * ─────────
 * USB-aware camera component with hot-plug detection.
 *
 * Key improvements over v1
 * ────────────────────────
 * • Listens to `navigator.mediaDevices.devicechange` — when you plug in a
 *   USB camera the list updates instantly, no page reload needed.
 * • Refresh button (⟳) to re-scan manually.
 * • "USB" badge shown next to cameras whose label contains "USB".
 * • Graceful `OverconstrainedError` fallback — if the selected camera can't
 *   satisfy the requested resolution, we retry with no resolution hint.
 * • `readyState >= 2` guard prevents blank frames being sent to the API.
 */

import React, {
  useRef, useEffect, useCallback, useState,
} from 'react';
import axios from 'axios';

const CAPTURE_INTERVAL = 1500;   // ms between API calls
const COLOR_KNOWN      = '#00e676';
const COLOR_UNKNOWN    = '#ff1744';

export default function Camera({ isRunning, onResult, apiUrl }) {
  const videoRef   = useRef(null);
  const captureRef = useRef(null);
  const overlayRef = useRef(null);
  const streamRef  = useRef(null);
  const timerRef   = useRef(null);

  const [cameras,        setCameras]        = useState([]);
  const [selectedCamera, setSelectedCamera] = useState('');
  const [isProcessing,   setIsProcessing]   = useState(false);
  const [error,          setError]          = useState(null);

  // ── Enumerate devices ────────────────────────────────────────────────
  const fetchCameras = useCallback(async () => {
    try {
      // A brief getUserMedia call forces the browser to label devices
      // (without it, labels are empty strings in Chrome).
      const tempStream = await navigator.mediaDevices.getUserMedia({ video: true });
      tempStream.getTracks().forEach(t => t.stop());
    } catch { /* permission denied — labels will be blank, but list still works */ }

    try {
      const devices = await navigator.mediaDevices.enumerateDevices();
      const cams    = devices.filter(d => d.kind === 'videoinput');
      setCameras(cams);

      // Keep selection valid; auto-select first if none chosen yet
      setCameras(prev => {
        // (prev is stale here — use cams directly)
        return cams;
      });
      setSelectedCamera(prev =>
        cams.some(c => c.deviceId === prev)
          ? prev
          : (cams[0]?.deviceId ?? ''),
      );
    } catch (err) {
      console.warn('enumerateDevices failed:', err.message);
    }
  }, []);

  // Enumerate on mount
  useEffect(() => { fetchCameras(); }, [fetchCameras]);

  // Hot-plug detection — fires when a USB camera is connected/disconnected
  useEffect(() => {
    const handler = () => {
      console.log('[Camera] devicechange event — refreshing camera list');
      fetchCameras();
    };
    navigator.mediaDevices.addEventListener('devicechange', handler);
    return () => navigator.mediaDevices.removeEventListener('devicechange', handler);
  }, [fetchCameras]);

  // ── Start stream ─────────────────────────────────────────────────────
  const startCamera = useCallback(async (deviceId) => {
    // Stop previous stream
    streamRef.current?.getTracks().forEach(t => t.stop());

    const tryStart = async (constraints) => {
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      setError(null);
    };

    try {
      // First attempt: request HD resolution for sharper faces
      await tryStart({
        audio: false,
        video: deviceId
          ? { deviceId: { exact: deviceId }, width: { ideal: 1280 }, height: { ideal: 720 } }
          : { facingMode: 'user',            width: { ideal: 1280 }, height: { ideal: 720 } },
      });
    } catch (err) {
      if (err.name === 'OverconstrainedError' || err.name === 'ConstraintNotSatisfiedError') {
        // USB cameras sometimes don't support the requested resolution — retry without hint
        console.warn('[Camera] Resolution constraint failed, retrying without hint…');
        try {
          await tryStart({
            audio: false,
            video: deviceId ? { deviceId: { exact: deviceId } } : true,
          });
        } catch (err2) {
          setError(`Camera failed: ${err2.message}`);
        }
      } else {
        setError(`Camera access denied: ${err.message}`);
      }
    }
  }, []);

  // ── Stop stream ──────────────────────────────────────────────────────
  const stopCamera = useCallback(() => {
    streamRef.current?.getTracks().forEach(t => t.stop());
    streamRef.current = null;
    if (videoRef.current) videoRef.current.srcObject = null;
    clearOverlay();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Frame capture ────────────────────────────────────────────────────
  const captureFrame = useCallback(() => {
    const video  = videoRef.current;
    const canvas = captureRef.current;
    if (!video || !canvas) return null;
    if (video.readyState < 2) return null;   // not enough data yet

    canvas.width  = video.videoWidth  || 640;
    canvas.height = video.videoHeight || 480;
    canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height);
    return canvas.toDataURL('image/jpeg', 0.7);
  }, []);

  // ── Overlay helpers ──────────────────────────────────────────────────
  const clearOverlay = useCallback(() => {
    const oc = overlayRef.current;
    if (!oc) return;
    oc.getContext('2d').clearRect(0, 0, oc.width, oc.height);
  }, []);

  const drawBox = useCallback((result) => {
    const video  = videoRef.current;
    const canvas = overlayRef.current;
    if (!video || !canvas) return;

    const vw = video.videoWidth  || 640;
    const vh = video.videoHeight || 480;
    if (canvas.width !== vw || canvas.height !== vh) {
      canvas.width  = vw;
      canvas.height = vh;
    }

    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, vw, vh);
    if (!result?.box) return;

    const [bx, by, bw, bh] = result.box;
    const isKnown = result.detected && result.name !== 'Unknown';
    const color   = isKnown ? COLOR_KNOWN : COLOR_UNKNOWN;

    // Bounding rectangle
    ctx.strokeStyle = color;
    ctx.lineWidth   = 2;
    ctx.strokeRect(bx, by, bw, bh);

    // Corner accents
    const C = 18;
    ctx.lineWidth = 3;
    [
      [bx,      by,      bx + C, by,      bx,      by + C],
      [bx + bw, by,      bx + bw - C, by, bx + bw, by + C],
      [bx,      by + bh, bx + C, by + bh, bx,      by + bh - C],
      [bx + bw, by + bh, bx + bw - C, by + bh, bx + bw, by + bh - C],
    ].forEach(([x1, y1, x2, y2, x3, y3]) => {
      ctx.beginPath(); ctx.moveTo(x2, y2); ctx.lineTo(x1, y1); ctx.lineTo(x3, y3); ctx.stroke();
    });

    // Label
    const label    = `${result.name}  ${Math.round((result.confidence ?? 0) * 100)}%`;
    const fontSize = Math.max(14, Math.round(bh * 0.07));
    ctx.font       = `bold ${fontSize}px 'Segoe UI', Arial`;
    const pad      = 6;
    const tw       = ctx.measureText(label).width;
    const lh       = fontSize + pad * 2;
    const lx       = bx;
    const ly       = Math.max(0, by - lh - 2);

    ctx.fillStyle   = isKnown ? 'rgba(0,230,118,0.25)' : 'rgba(255,23,68,0.25)';
    ctx.fillRect(lx, ly, tw + pad * 2, lh);
    ctx.strokeStyle = color; ctx.lineWidth = 1;
    ctx.strokeRect(lx, ly, tw + pad * 2, lh);
    ctx.fillStyle = '#fff';
    ctx.fillText(label, lx + pad, ly + fontSize + pad - 2);
  }, []);

  // ── Send frame to backend ────────────────────────────────────────────
  const sendFrame = useCallback(async () => {
    if (isProcessing) return;
    const imageData = captureFrame();
    if (!imageData) return;

    setIsProcessing(true);
    try {
      const { data } = await axios.post(
        `${apiUrl}/recognize`,
        { image: imageData },
        { timeout: 12_000 },
      );
      drawBox(data);
      onResult(data);
    } catch (err) {
      console.warn('Recognition error:', err.message);
      clearOverlay();
      onResult(null);
    } finally {
      setIsProcessing(false);
    }
  }, [isProcessing, captureFrame, apiUrl, drawBox, clearOverlay, onResult]);

  // ── Start / stop loop ────────────────────────────────────────────────
  useEffect(() => {
    if (isRunning) {
      startCamera(selectedCamera);
      timerRef.current = setInterval(sendFrame, CAPTURE_INTERVAL);
    } else {
      clearInterval(timerRef.current);
      stopCamera();
      onResult(null);
    }
    return () => clearInterval(timerRef.current);
  }, [isRunning, selectedCamera]); // eslint-disable-line react-hooks/exhaustive-deps

  // Keep interval callback fresh
  useEffect(() => {
    if (!isRunning) return;
    clearInterval(timerRef.current);
    timerRef.current = setInterval(sendFrame, CAPTURE_INTERVAL);
    return () => clearInterval(timerRef.current);
  }, [sendFrame, isRunning]);

  // ── Camera switch ────────────────────────────────────────────────────
  const handleCameraChange = (e) => {
    setSelectedCamera(e.target.value);
    if (isRunning) startCamera(e.target.value);
  };

  const isUsbCamera = (label) =>
    /usb|external|logitech|webcam|c\d{3}|c\d{4}|hd pro|brio|streamcam/i.test(label);

  // ── Render ────────────────────────────────────────────────────────────
  return (
    <div className="camera-container">

      {/* Camera selector */}
      <div className="camera-selector">
        <label htmlFor="cam-select">Camera</label>
        <div className="cam-select-row">
          <select
            id="cam-select"
            value={selectedCamera}
            onChange={handleCameraChange}
            disabled={cameras.length === 0}
          >
            {cameras.length === 0 && (
              <option value="">No cameras found</option>
            )}
            {cameras.map((cam, i) => {
              const label = cam.label || `Camera ${i + 1}`;
              const usb   = isUsbCamera(label);
              return (
                <option key={cam.deviceId} value={cam.deviceId}>
                  {usb ? '🔌 ' : '📷 '}{label}
                </option>
              );
            })}
          </select>
          <button
            className="btn-icon-sm"
            onClick={fetchCameras}
            title="Refresh camera list (use after plugging in a USB camera)"
          >
            ⟳
          </button>
        </div>
        {cameras.length > 0 && (
          <span className="cam-count">
            {cameras.length} camera{cameras.length !== 1 ? 's' : ''} detected
            {cameras.some(c => isUsbCamera(c.label)) && ' · 🔌 USB detected'}
          </span>
        )}
      </div>

      {/* Video + overlay */}
      <div className="video-wrapper">
        <video ref={videoRef} autoPlay playsInline muted className="video-feed" />
        <canvas ref={overlayRef} className="overlay-canvas" />

        {!isRunning && (
          <div className="camera-placeholder">
            <div className="placeholder-icon">📷</div>
            <p>Press <strong>Start Recognition</strong> to begin</p>
            {cameras.length === 0 && (
              <p style={{ color: 'var(--red)', fontSize: '0.8rem' }}>
                No cameras detected — plug in a USB camera and click ⟳
              </p>
            )}
          </div>
        )}

        {isRunning && isProcessing && (
          <div className="processing-indicator">
            <span className="spinner" /> Analysing…
          </div>
        )}
      </div>

      {/* Hidden capture canvas */}
      <canvas ref={captureRef} style={{ display: 'none' }} />

      {error && <div className="error-banner">⚠️ {error}</div>}
    </div>
  );
}
